export function nextPermutation(values          )           {
const a=[...values];let i=a.length-2;while(i>=0&&a[i]>=a[i+1])i--;if(i>=0){let j=a.length-1;while(a[j]<=a[i])j--;[a[i],a[j]]=[a[j],a[i]];}let l=i+1,r=a.length-1;while(l<r){[a[l],a[r]]=[a[r],a[l]];l++;r--;}return a;
}

